                    "start_line": {"type": "integer", "description": "First line to show (1-based, inclusive)."},
                    "end_line": {"type": "integer", "description": "Last line to show (inclusive)."},
                },
                "required": ["path"],
            },
        },
    },
    {
        "type": "function",
        "function": {
